CREATE TABLE proj25_students (student_id INTEGER PRIMARY KEY, student_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE);
CREATE TABLE proj25_courses (course_id INTEGER PRIMARY KEY, course_code TEXT NOT NULL UNIQUE, course_title TEXT NOT NULL);
CREATE TABLE proj25_enrollments (student_id INTEGER NOT NULL, course_id INTEGER NOT NULL, grade INTEGER CHECK (grade BETWEEN 0 AND 100), PRIMARY KEY (student_id, course_id));
